CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultAsset_AfterDelete] ON [dbo].[ResponsibilityRuleResultAsset] AFTER DELETE AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted D INNER JOIN [dbo].[Asset] A ON D.AssetID = A.ID WHERE D.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted D INNER JOIN [dbo].[Asset] A ON D.AssetTypeID = A.AssetTypeID WHERE D.AssetID = 0; END

CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultAsset_AfterInsert] ON [dbo].[ResponsibilityRuleResultAsset] AFTER INSERT AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN [dbo].[Asset] A ON I.AssetID = A.ID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] R ON I.RuleID = R.ID WHERE R.LastRunOn IS NOT NULL AND I.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN [dbo].[Asset] A ON I.AssetID = A.ID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] R ON I.RuleID = R.ID WHERE R.LastRunOn IS NOT NULL AND I.AssetID = 0; END
